def main():
    files = {}
    for name in os.listdir(OVERLAY_DIR):
        if name.startswith('overlay_') and name.endswith('.c'):
            path = os.path.join(OVERLAY_DIR, name)
            with open(path, 'r', encoding='utf-8') as f:
                files[path] = f.read()

    applied = 0
    for fo, data in HAND_PORTS.items():
        new_name = data['new_name']
        block = data['block']
        for path in files:
            content = files[path]
            if fo not in content:
                continue
            asm_marker = f"@asm        {fo}.."
            asm_idx = content.find(asm_marker)
            if asm_idx < 0:
                continue
            status_idx = content.find(" * @status", asm_idx)
            if status_idx < 0:
                continue
            insertion = block + "\n"
            content = content[:status_idx] + insertion + content[status_idx:]
            func_def_pat = re.compile(
                r'\*/\n(int func_' + re.escape(fo[2:].upper()) + r'_)([a-zA-Z_]+)(\(.*?\))',
                re.MULTILINE)
            content = func_def_pat.sub(rf'*/\nint {new_name}\3', content, count=1)
            files[path] = content
            applied += 1
            break

    for path, content in files.items():
        with open(path, 'w', encoding='utf-8') as f:
            f.write(content)

    print(f"[reapply] applied hand-port to {applied}/{len(HAND_PORTS)} functions")


if __name__ == '__main__':
    main()
